/**
 * Wordpress Node - Version 1
 * Discriminator: resource=user, operation=update
 */


interface Credentials {
  wordpressApi: CredentialReference;
  wordpressOAuth2Api: CredentialReference;
}

/** Update a post */
export type WordpressV1UserUpdateParams = {
  resource: 'user';
  operation: 'update';
/**
 * The authentication method to use
 * @default basicAuth
 */
    authType?: 'basicAuth' | 'oAuth2' | Expression<string>;
/**
 * Unique identifier for the user
 */
    userId: string | Expression<string>;
/**
 * Update Fields
 * @default {}
 */
    updateFields?: {
    /** Login name for the user
     */
    username?: string | Expression<string>;
    /** Display name for the user
     */
    name?: string | Expression<string>;
    /** First name for the user
     */
    firstName?: string | Expression<string>;
    /** Last name for the user
     */
    lastName?: string | Expression<string>;
    /** The email address for the user
     */
    email?: string | Expression<string>;
    /** Password for the user (never included)
     */
    password?: string | Expression<string>;
    /** URL of the user
     */
    url?: string | Expression<string>;
    /** Description of the user
     */
    description?: string | Expression<string>;
    /** The nickname for the user
     */
    nickname?: string | Expression<string>;
    /** An alphanumeric identifier for the user
     */
    slug?: string | Expression<string>;
  };
};

export type WordpressV1UserUpdateNode = {
  type: 'n8n-nodes-base.wordpress';
  version: 1;
  config: NodeConfig<WordpressV1UserUpdateParams> & { credentials?: Credentials };
};